const $=id=>document.getElementById(id);
let state={summary:null,resumes:[],accounts:[],applications:[],blockers:[],answers:[],settings:null,profile:null};
async function api(path,options={}){const response=await fetch(path,{cache:'no-store',...options});const text=await response.text();let body={};try{body=text?JSON.parse(text):{};}catch{body={error:text||'Request failed.'};}if(!response.ok){const error=Error(body.error||'Request failed.');error.status=response.status;throw error;}return body;}
function message(text){$('auto-message').textContent=text||'';}
function panel(name){document.querySelectorAll('.auto-panel').forEach(p=>p.hidden=p.id!==`panel-${name}`);document.querySelectorAll('.auto-tabs [role=tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.panel===name)));}
function card(label,value,hint=''){return `<div class="analytics-card"><span>${label}</span><strong>${value}</strong>${hint?`<small>${hint}</small>`:''}</div>`;}
function empty(text){return `<p class="management-empty">${text}</p>`;}
function esc(value){return String(value??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function renderDashboard(){const s=state.summary||{};$('worker-status').textContent=s.worker?.configured?`Worker configured · ${s.worker.model||'model not reported'}`:'External Skyvern/Ollama worker not configured';$('dashboard-cards').innerHTML=[card('Matching jobs',s.counts?.matched||0),card('Queued',s.counts?.queued||0),card('In progress',s.counts?.inProgress||0),card('Awaiting review',s.counts?.readyForReview||0),card('Submitted',s.counts?.submitted||0),card('Open blockers',s.counts?.blockers||0),card('Failures',s.counts?.failed||0)].join('');$('activity-list').innerHTML=(s.activity||[]).map(a=>`<article class="auto-row"><strong>${esc(a.event_type)}</strong><span>${esc(a.message)}</span><small>${new Date(a.created_at).toLocaleString()}</small></article>`).join('')||empty('No activity yet.');}
function renderProfile(){const p=state.profile?.profile||{};$('profile-summary').innerHTML=[['Email',state.profile?.email],['First Name',p.first_name],['Last Name',p.last_name],['Mobile Number',p.mobile],['Status',p.visa_status],['Location',p.location],['Education',p.education],['Experience',p.experience],['Skills',p.skills],['Certifications',p.certifications],['Work authorization',p.work_authorization],['Sponsorship needs',p.sponsorship_needs],['Salary expectations',p.salary_expectations],['Job preferences',p.job_preferences],['Relocation preferences',p.relocation_preferences]].map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v||'Not provided')}</dd>`).join('');}
function renderResumes(){$('resume-list').innerHTML=state.resumes.map(r=>`<article class="auto-row"><strong>${esc(r.name)}</strong><span>${esc(r.file_name)}${r.is_default?' · Default':''}</span><small>${esc(r.extraction_status||'stored')} · ${new Date(r.created_at).toLocaleString()}</small><div><button data-resume-default="${r.id}">Set default</button><button data-resume-delete="${r.id}" class="danger">Delete</button></div></article>`).join('')||empty('No resumes uploaded yet.');$('match-resume').innerHTML='<option value="">Default resume</option>'+state.resumes.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}${r.is_default?' (default)':''}</option>`).join('');}
function renderAccounts(){const order=['linkedin','indeed','dice','gmail'];$('account-list').innerHTML=order.map(provider=>{const a=state.accounts.find(x=>x.provider===provider)||{provider,status:'not_connected'};return `<article class="account-card"><h3>${provider==='linkedin'?'LinkedIn':provider.charAt(0).toUpperCase()+provider.slice(1)}</h3><p>${esc(a.status.replaceAll('_',' '))}</p><small>Last verification: ${a.last_verified_at?new Date(a.last_verified_at).toLocaleString():'Never'}</small><div><button data-connect="${provider}">Connect</button><button data-disconnect="${provider}">Disconnect</button></div></article>`}).join('');}
function renderApplications(){const filter=$('tracker-status').value;const apps=state.applications.filter(a=>!filter||a.status===filter);$('tracker-list').innerHTML=apps.map(a=>`<article class="auto-row"><strong>${esc(a.company_name)} — ${esc(a.job_title)}</strong><span>${esc(a.status)} · score ${a.match_score??'—'} · ${esc(a.blocker_status||'No blocker')}</span><a href="${esc(a.job_url)}" target="_blank" rel="noopener noreferrer">Job link ↗</a><small>Last activity ${a.last_activity_at?new Date(a.last_activity_at).toLocaleString():'—'} · ID ${esc(a.id)}</small></article>`).join('')||empty('No applications found. Run Job Matching first.');}
function renderBlockers(){$('blocker-list').innerHTML=state.blockers.map(b=>`<article class="auto-row"><strong>${esc(b.company_name)} — ${esc(b.job_title)}</strong><span>${esc(b.reason)} · ${esc(b.status)}</span><p>${esc(b.question||'No question captured.')}</p><form data-blocker="${b.id}" class="inline"><input name="answer" placeholder="Answer this blocker"><label class="check-row"><input name="save" type="checkbox" checked> Save answer</label><button class="primary">Resolve</button></form></article>`).join('')||empty('No blockers.');}
function renderAnswers(){$('answer-list').innerHTML=state.answers.map(a=>`<article class="auto-row"><strong>${esc(a.question)}</strong><span>${esc(a.answer)}</span><small>${esc(a.answer_type)} · approved ${new Date(a.approved_at).toLocaleDateString()}</small><button data-answer-delete="${a.id}" class="danger">Delete</button></article>`).join('')||empty('No saved answers yet.');}
function renderSettings(){if(!state.settings)return;$('daily-limit').value=state.settings.daily_limit;$('minimum-score').value=state.settings.minimum_score;$('require-review').checked=Boolean(state.settings.require_review);}
function renderAll(){renderDashboard();renderProfile();renderResumes();renderAccounts();renderApplications();renderBlockers();renderAnswers();renderSettings();}
async function load(){try{const session=await api('/api/session');if(session.status!=='approved'){location.replace('/');return;}document.body.classList.add('has-access');$('auto-apply-page').hidden=false;$('section-role').textContent=session.role==='admin'?'Admin':session.role==='coadmin'?'Coadmin':'User';message('Loading AI Auto Apply…');const data=await api('/api/auto-apply/bootstrap');state={...state,...data};renderAll();message('');}catch(error){if(error.status===403)location.replace('/');else{document.body.classList.add('has-access');$('auto-apply-page').hidden=false;message(error.message);}}}
async function refresh(){const data=await api('/api/auto-apply/bootstrap');state={...state,...data};renderAll();}
document.querySelectorAll('.auto-tabs [role=tab]').forEach(button=>button.addEventListener('click',()=>panel(button.dataset.panel)));
$('section-logout').addEventListener('click',async()=>{await api('/api/logout',{method:'POST'});location.replace('/');});
$('refresh-auto').addEventListener('click',refresh);
$('resume-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData();fd.append('name',$('resume-name').value);fd.append('isDefault',$('resume-default').checked?'true':'false');fd.append('file',$('resume-file').files[0]);try{await api('/api/auto-apply/resumes',{method:'POST',body:fd});e.target.reset();await refresh();message('Resume uploaded.');}catch(error){message(error.message);}});
$('resume-list').addEventListener('click',async e=>{const id=e.target.dataset.resumeDefault||e.target.dataset.resumeDelete;if(!id)return;try{await api(`/api/auto-apply/resumes/${encodeURIComponent(id)}`,{method:e.target.dataset.resumeDelete?'DELETE':'PUT',headers:{'Content-Type':'application/json'},body:e.target.dataset.resumeDelete?undefined:JSON.stringify({isDefault:true})});await refresh();}catch(error){message(error.message);}});
$('account-list').addEventListener('click',async e=>{const provider=e.target.dataset.connect||e.target.dataset.disconnect;if(!provider)return;try{const action=e.target.dataset.connect?'connect':'disconnect';const result=await api('/api/auto-apply/accounts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider,action})});await refresh();message(result.message);}catch(error){message(error.message);}});
$('match-form').addEventListener('submit',async e=>{e.preventDefault();try{const result=await api('/api/auto-apply/matches',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({category:$('match-category').value,minScore:Number($('match-min').value),resumeId:$('match-resume').value})});state.applications=result.items;renderApplications();panel('tracker');message(`${result.items.length} matching jobs created or updated.`);}catch(error){message(error.message);}});
$('agent-form').addEventListener('submit',async e=>{e.preventDefault();try{const result=await api('/api/auto-apply/agent/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({applicationId:$('agent-application-id').value,instructions:$('agent-instructions').value})});await refresh();message(result.message);}catch(error){message(error.message);}});
for(const [id,action] of [['start-agent','start'],['pause-agent','pause'],['resume-agent','resume'],['stop-agent','stop']])$(id).addEventListener('click',async()=>{try{const result=await api('/api/auto-apply/agent/control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});await refresh();message(result.message);}catch(error){message(error.message);}});
$('blocker-list').addEventListener('submit',async e=>{if(!e.target.dataset.blocker)return;e.preventDefault();try{await api('/api/auto-apply/blockers/answer',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({blockerId:e.target.dataset.blocker,answer:e.target.answer.value,saveAnswer:e.target.save.checked})});await refresh();message('Blocker resolved.');}catch(error){message(error.message);}});
$('answer-form').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/auto-apply/answers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:$('answer-question').value,answer:$('answer-text').value,answerType:$('answer-type').value})});e.target.reset();await refresh();message('Answer saved.');}catch(error){message(error.message);}});
$('answer-list').addEventListener('click',async e=>{if(!e.target.dataset.answerDelete)return;try{await api(`/api/auto-apply/answers/${encodeURIComponent(e.target.dataset.answerDelete)}`,{method:'DELETE'});await refresh();}catch(error){message(error.message);}});
$('tracker-status').addEventListener('change',renderApplications);
$('settings-form').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/auto-apply/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({dailyLimit:Number($('daily-limit').value),minimumScore:Number($('minimum-score').value),requireReview:$('require-review').checked})});await refresh();message('Settings saved.');}catch(error){message(error.message);}});
load();
